SELECT array_to_string(array_agg(t.pid), ',') AS id, purchase_org_name AS purchaseOrgName, supplier_name AS supplierName, images_url AS imagesUrl, sku_no AS skuNo, productName, spu_no AS spuNo, avg(tax_price) AS taxPrice, round(SUM(orderAmount) / sum(t.purchase_qty)::numeric ,4) AS avgPrice, COUNT(t.id) AS orderQty, SUM(orderAmount) AS orderAmount, max(createTime) AS createTime FROM ( SELECT pod.id AS pid, po.purchase_org_name, pos.supplier_name, pd.images_url, pod.sku_no, pd."name" AS productName, pi.spu_no, pod.tax_price AS tax_price, po.id AS id, pod.purchase_amount AS orderAmount, po.create_time AS createTime, po.purchase_date, pod.purchase_qty FROM purchase_order_detail pod LEFT JOIN purchase_order po ON pod.purchase_order_id = po.id LEFT JOIN purchase_order_supplier pos ON pos.purchase_order_id = po.id LEFT JOIN product_detail pd ON pod.sku_id = pd.id LEFT JOIN product_info pi ON pi.id = pd.product_id WHERE pod.is_deleted = FALSE AND po.approve_status = 'approve' AND po.is_deleted = FALSE AND pos.is_deleted = FALSE AND pd.is_deleted = FALSE AND pi.is_deleted = FALSE AND po.purchase_date >= #{params.billDateList[0]} AND (#{params.billDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > po.purchase_date
AND pod.sku_no IN
#{item}
AND pi.spu_no IN
#{item}
AND po.delivery_warehouse_id in
#{item}
AND po.purchase_org_id in
#{item}
AND pos.supplier_id in
#{item}
${params.permissionSql}
)t GROUP BY purchase_org_name, supplier_name, images_url, sku_no, productName, spu_no ORDER BY
${item.field} ${item.sort}
purchase_org_name, supplier_name, createTime DESC

